using JamunaBank.Procurement.API.DTOs;using JamunaBank.Procurement.API.Repositories.Interfaces;using JamunaBank.Procurement.API.Services.Interfaces;
namespace JamunaBank.Procurement.API.Services.Implementations;
public sealed class RequisitionFormService(IRequisitionFormRepository repository,ICurrentUserService user):IRequisitionFormService
{public Task<ReadyRequisitionPageDto>GetReadyAsync(string?search,string?type,long?divisionId,DateOnly?from,DateOnly?to,int page,int size,CancellationToken ct){if(divisionId is<=0)throw new ArgumentOutOfRangeException(nameof(divisionId));if(from.HasValue&&to.HasValue&&from>to)throw new ArgumentException("From date cannot be after to date.");return repository.GetReadyAsync(string.IsNullOrWhiteSpace(search)?null:search.Trim(),string.IsNullOrWhiteSpace(type)?null:type.Trim().ToUpperInvariant(),divisionId,from,to,page,size,ct);}public Task<RequisitionFormDto?>GetFormAsync(long id,CancellationToken ct){if(id<=0)throw new ArgumentOutOfRangeException(nameof(id));return repository.GetFormAsync(id,user.EmployeeId,ct);}}
